"""Input checks for upstream's evaluation; scoring stays in src.utils.

Constants come from GDiffRetro e727678/code/unknown_class/stage2:
run_get_results.sh, configs/uspto_sample.yml, configs/uspto_gdiffretro.yml.
These checks do not filter, canonicalize, reorder candidates or rescore them.
"""
from numbers import Integral
from pathlib import Path
import pickle
import re

import pandas as pd

PROTOCOL = 'gdiffretro_official_unknown'
N_SAMPLES = 300
N_STEPS = 100
SEED = 0
BATCH_SIZE = 64


def validate_sampling(config):
    required = {'n_samples': N_SAMPLES, 'n_steps': N_STEPS, 'sample_seed': SEED,
                'batch_size': BATCH_SIZE}
    for name, expected in required.items():
        if isinstance(config.get(name), bool) or config.get(name) != expected:
            raise ValueError(f'Official default testing requires {name}={expected}')
    if config.get('oracle_size') or not config.get('linker_size_model'):
        raise ValueError('Official testing requires the learned size sampler, not true sizes')
    if config.get('max_batches') is not None:
        raise ValueError('Do not truncate batches in official testing; use an explicitly defined complete-product subset for diagnostics')


def validate_table(table, source=None):
    if not {'uuid', 'product'}.issubset(table.columns) or table.empty:
        raise ValueError('Official test table needs uuid and product, including zero-linker rows')
    if table[['uuid', 'product']].isna().any().any() or table.uuid.duplicated().any():
        raise ValueError('Missing or duplicated test identities')
    if not table.uuid.is_monotonic_increasing:
        raise ValueError('The official test table must be sorted by UUID')
    if '_source_row' in table:
        validate_reaction_units(table)
    if source is not None:
        validate_table(source)
        expected = source
        left = list(table[['uuid', 'product']].itertuples(index=False, name=None))
        right = list(expected.sort_values('uuid')[['uuid', 'product']].itertuples(index=False, name=None))
        if left != right:
            raise ValueError('Official default testing needs the full declared test split, including every product component and zero-linker row')


def validate_reaction_units(metadata):
    """Upstream product concatenation must combine components of ONE reaction."""
    if not {'product', '_source_row'}.issubset(metadata.columns):
        raise ValueError('Reaction identity metadata requires product and _source_row')
    if metadata[['product', '_source_row']].isna().any().any():
        raise ValueError('Missing reaction identity')
    counts = metadata.groupby('product')['_source_row'].nunique()
    conflicts = counts[counts > 1]
    if len(conflicts):
        raise ValueError(f'{len(conflicts)} products contain multiple source reactions; upstream concatenation would merge different examples. Resolve dataset reaction identities before scoring.')


def validate_stage1(path, table):
    path = Path(path)
    if '_w_class' in path.stem.lower() or re.search(r'(^|[_-])known[_-]?class([_-]|$)', path.stem.lower()):
        raise ValueError('Use an unknown-class Stage1 count file')
    # This is the local pkl generated by the official Stage1 evaluation script.
    with path.open('rb') as f:
        counts = pickle.load(f)
    if not isinstance(counts, dict):
        raise ValueError('Stage1 output must map product SMILES to correct-center counts')
    for product in table['product'].unique():
        value = counts.get(product)
        if isinstance(value, bool) or not isinstance(value, Integral) or not 0 <= value <= N_SAMPLES:
            raise ValueError(f'Missing/invalid Stage1 300-draw count for product {product}')
    return counts


def validate_results(results, table):
    expected_columns = ['uuid'] + [str(i) for i in range(1, N_SAMPLES + 2)]
    if list(results.columns) != expected_columns:
        raise ValueError('Expected 300 candidates and the decoded XYZ reference for every row')
    if results.uuid.duplicated().any() or set(results.uuid) != set(table.uuid):
        raise ValueError('Test coverage differs: do not omit missing/failed samples from the denominator')
    if results.isna().any().any():
        raise ValueError('Blank decoded fields cannot be silently removed or replaced; inspect the upstream decoding failure')


def preflight(config, test_table_path, stage1_path, source_table_path):
    validate_sampling(config)
    table = pd.read_csv(test_table_path)
    source = pd.read_csv(source_table_path)
    validate_table(table, source)
    validate_stage1(stage1_path, table)
    return table
